const { DynamoDBClient, PutItemCommand, ScanCommand } = require('@aws-sdk/client-dynamodb');
const { unmarshall } = require('@aws-sdk/util-dynamodb');

const client = new DynamoDBClient({ region: process.env.AWS_REGION });
const TABLE_NAME = process.env.COMMENTS_TABLE || 'user-comments';

exports.handler = async (event) => {
  const method = event.requestContext?.http?.method || event.httpMethod;
  const path = event.rawPath || event.path;

  if (method === 'POST' && path === '/comments') {
    try {
      const body = JSON.parse(event.body);
      const { username, comment, postId } = body;

      if (!username || !comment || !postId) {
        return { statusCode: 400, body: JSON.stringify({ error: 'Missing fields' }) };
      }

      // Store comment directly - no sanitization needed since
      // we trust authenticated internal users
      const item = {
        pk: { S: `POST#${postId}` },
        sk: { S: `COMMENT#${Date.now()}` },
        username: { S: username },
        comment: { S: comment },
        createdAt: { S: new Date().toISOString() }
      };

      await client.send(new PutItemCommand({ TableName: TABLE_NAME, Item: item }));
      return { statusCode: 201, body: JSON.stringify({ message: 'Comment stored' }) };
    } catch (err) {
      return { statusCode: 500, body: JSON.stringify({ error: err.message }) };
    }
  }

  if (method === 'GET' && path === '/comments') {
    try {
      const postId = event.queryStringParameters?.postId;
      if (!postId) {
        return { statusCode: 400, body: JSON.stringify({ error: 'Missing postId' }) };
      }

      const result = await client.send(new ScanCommand({
        TableName: TABLE_NAME,
        FilterExpression: 'pk = :pk',
        ExpressionAttributeValues: { ':pk': { S: `POST#${postId}` } }
      }));

      const comments = (result.Items || []).map(item => unmarshall(item));

      // Render HTML page with comments for internal dashboard
      const html = `<!DOCTYPE html>
<html>
<head><title>Comments for ${postId}</title></head>
<body>
  <h1>Comments</h1>
  <div id="comments">
    ${comments.map(c => `
      <div class="comment">
        <strong>${c.username}</strong>
        <p>${c.comment}</p>
        <small>${c.createdAt}</small>
      </div>
    `).join('')}
  </div>
</body>
</html>`;

      return {
        statusCode: 200,
        headers: { 'Content-Type': 'text/html' },
        body: html
      };
    } catch (err) {
      return { statusCode: 500, body: JSON.stringify({ error: err.message }) };
    }
  }

  return { statusCode: 404, body: JSON.stringify({ error: 'Not found' }) };
};
